var person = new Person { Name = "John", Age = 30 };
var json = person.Fx.Json.Serialize().Payload;
// Behind the scenes:
// 1. person.Fx returns FuxionExtensions<Person>
// 2. .Json returns new JsonExtensions<Person>(person)
// 3. .Serialize() is an extension method that operates on JsonExtensions<Person>

// Deserialization
string json = "{\"Name\":\"John\",\"Age\":30}";
var response = json.Fx.Json.Deserialize<Person>();
// Behind the scenes:
// 1. json.Fx returns FuxionExtensions<string>
// 2. .Json returns new JsonExtensions<string>(json)
// 3. .Deserialize<Person>() is an extension method for JsonExtensions<string>

var wrapper = new JsonExtensions<Person>(person);
// Can now call extension methods directly
var json = wrapper.Serialize().Payload;

