}

// Creating a thread-safe list
var safeList = new Locker<List<string>>(new List<string>());

// Synchronous read operation
safeList.Read(list => 
{
    Console.WriteLine($"Count: {list.Count}");
    foreach (var item in list)
        Console.WriteLine(item);
});

// Synchronous read with return value
var count = safeList.Read(list => list.Count);

// Synchronous write operation
safeList.Write(list => 
{
    list.Add("New Item");
    list.Sort();
});

// Asynchronous operations
await safeList.ReadAsync(list => Console.WriteLine($"Count: {list.Count}"));
await safeList.WriteAsync(list => list.Add("Async Item"));

