// Global sequential execution (all tasks using this profile share one queue)
var globalProfile = new ConcurrencyProfile { Sequentially = true, ByInstance = false };

// Per-instance sequential execution (each object instance has its own queue)
var instanceProfile = new ConcurrencyProfile { Sequentially = true, ByInstance = true };

example.code:
public class ConcurrentTaskManager
{
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(5); // Max 5 concurrent tasks

    public async Task ExecuteWithConcurrencyControlAsync(Func<Task> work, CancellationToken ct = default)
    {
        if (!await _semaphore.WaitAsync(0, ct)) // Don't wait, fail immediately
        {
            throw new TaskCanceledByConcurrencyException();
        }

        try
        {
            await work();
        }
        finally
        {
            _semaphore.Release();
        }
    }
}

// Usage
try
{
    await manager.ExecuteWithConcurrencyControlAsync(async () => 
    {
        await ProcessDataAsync();
    });
}
catch (TaskCanceledByConcurrencyException)
{
    Console.WriteLine("Task was canceled due to concurrency limits");
    // Handle concurrency-specific cancellation
}
catch (TaskCanceledException)
{
    Console.WriteLine("Task was canceled for other reasons");
    // Handle general cancellation
}

// Create and start a simple task
var task = TaskManager.StartNew(() => Console.WriteLine("Hello"));

// Create a task with parameters
var task2 = TaskManager.StartNew(
    (name, age) => Console.WriteLine($"{name} is {age}"), 
    "John", 
    30
);

// Create a task with return value
var resultTask = TaskManager.StartNew(() => 42);
int result = await resultTask;

// Access current task from within a managed task
TaskManager.StartNew(() => 
{
    var current = TaskManager.Current; // Gets the current task
    Console.WriteLine($"Task ID: {current?.Id}");
});

// Create task with concurrency profile
var task3 = TaskManager.StartNew(
    () => DoWork(),
    concurrencyProfile: ConcurrencyProfile.MaxConcurrency(4)
);

// Create without starting
